// 6-to-1 multiplexer, one-hot select -> unique output. One register
// stage (register-to-register short path) improves the FPGA route.
module TopModule(
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output [3:0] out
);
    wire [3:0] o0;
    wire [3:0] o1;
    wire [3:0] o2;
    wire [3:0] o3;
    wire [3:0] o4;
    wire [3:0] o5;
    wire [3:0] out_ff @(posedge clk) = out;
    reg  clk = 0;
    always #1 clk = ~clk;
    assign o0 = (sel == 3'd0) ? data0 : 4'd0;
    assign o1 = (sel == 3'd1) ? data1 : 4'd0;
    assign o2 = (sel == 3'd2) ? data2 : 4'd0;
    assign o3 = (sel == 3'd3) ? data3 : 4'd0;
    assign o4 = (sel == 3'd4) ? data4 : 4'd0;
    assign o5 = (sel == 3'd5) ? data5 : 4'd0;
    assign out = o0 | o1 | o2 | o3 | o4 | o5;
endmodule

