samples.raw_completion:
// 6-to-1 multiplexer with a simple switch-case statement. The switch-case
// statement is implemented with a large nested case statement, which is
// unfolded into a large chain of AND/OR gates (the critical path is roughly
// the longest path in the critical path graph). The critical path is roughly
// 10ns, which is fast enough for Fmax around 100MHz.
module TopModule(
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output [3:0] out
);
    wire [3:0] d;
    always @(*) begin
        case (sel)
            0: d = data0;
            1: d = data1;
            2: d = data2;
            3: d = data3;
            4: d = data4;
            5: d = data5;
            default: d = 4'b0;
        endcase
    end
    assign out = d;
endmodule

