// 6-to-1 multiplexer, one-hot select (named wires for the mux bits make it
// easy to change to a partial one-hot selector).
module TopModule(
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output [3:0] out
);
    wire [3:0] mux0_out;
    wire [3:0] mux1_out;
    wire [3:0] mux2_out;
    wire [3:0] mux3_out;
    wire [3:0] mux4_out;
    wire [3:0] mux5_out;
    wire [3:0] mux6_out;
    wire [3:0] mux7_out;
    assign mux0_out = (sel == 0) ? data0 : 4'd0;
    assign mux1_out = (sel == 1) ? data1 : 4'd0;
    assign mux2_out = (sel == 2) ? data2 : 4'd0;
    assign mux3_out = (sel == 3) ? data3 : 4'd0;
    assign mux4_out = (sel == 4) ? data4 : 4'd0;
    assign mux5_out = (sel == 5) ? data5 : 4'd0;
    assign mux6_out = (sel == 6) ? data0 : 4'd0;
    assign mux7_out = (sel == 7) ? data1 : 4'd0;
    assign out = mux0_out | mux1_out | mux2_out | mux3_out | mux4_out | mux5_out | mux6_out | mux7_out;
endmodule

